        "zpool create -O mountpoint=legacy manual /dev/vdc1",
        "echo otherpass | zfs create "
        + "-o encryption=aes-256-gcm -o keyformat=passphrase manual/encrypted",
        "zfs create -o encryption=aes-256-gcm -o keyformat=passphrase "
